#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    string s;
    cin >> s;

    int depth = 0;
    string out;
    for (char ch : s) {
        if (ch == '(') {
            if (depth > 0) out += ch;
            depth++;
        } else {
            depth--;
            if (depth > 0) out += ch;
        }
    }
    cout << (out.empty() ? "empty" : out) << "\n";

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();

        int depth = 0;
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch == '(') {
                if (depth > 0) out.append(ch);
                depth++;
            } else {
                depth--;
                if (depth > 0) out.append(ch);
            }
        }
        System.out.println(out.length() == 0 ? "empty" : out.toString());
    }
}
